/**
 * 远程数据 Context
 *
 * 作用：
 * - App 启动时预取所有远程模块数据（data/*.json）
 * - 各数据 hook 通过 useRemoteDataStore 读取远程数据
 * - 前台页面展示时，远程数据优先于本地默认数据
 * - 后台管理页面不受影响，继续使用本地 localStorage 数据
 *
 * 为什么用 Context 而不是每个 hook 各自 fetch？
 * 1. 避免多个 hook 同时发起相同 fetch 请求
 * 2. 统一缓存机制（5 分钟 sessionStorage）
 * 3. 方便一键刷新所有远程数据
 *
 * 🔴 防闪烁设计：
 * - 首帧同步读取 sessionStorage 缓存（如果有 5 分钟内的缓存），避免首屏 fallback 数据 → 远程数据 的跳变
 * - 所有模块 fetch 完成后一次性 setState，避免 11 个模块逐个 setModules 导致 11 次全树重渲染
 * - Context value 用 useMemo 缓存，避免每次渲染生成新对象引用导致消费者级联重渲染
 * - fetch 失败的模块写入 failedModules 标记，后续不再重试（除非手动 refresh）
 * - 前台 preferRemote 模式：初始直接显示缓存数据（无 loading 态），远程数据到达后静默替换
 */

import {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  useMemo,
  useRef,
  type ReactNode,
} from 'react';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { useGithubConfig } from '@/hooks/useGithubConfig';

export type RemoteDataModule =
  | 'products'
  | 'advantages'
  | 'testimonials'
  | 'features'
  | 'heroSlides'
  | 'about'
  | 'news'
  | 'categories'
  | 'footer'
  | 'seo'
  | 'privacy'
  | 'translations'
  | 'settings'
  | 'factoryVideo'
  | 'faqs'
  | 'blog'
  | 'blogSettings'
  | 'quoteSection';

/** 模块 → data/ 路径映射 */
const MODULE_PATHS: Record<RemoteDataModule, string> = {
  products: 'data/products.json',
  advantages: 'data/advantages.json',
  testimonials: 'data/testimonials.json',
  features: 'data/features.json',
  heroSlides: 'data/hero-slides.json',
  about: 'data/about.json',
  news: 'data/news.json',
  categories: 'data/categories.json',
  footer: 'data/footer.json',
  seo: 'data/seo.json',
  privacy: 'data/privacy.json',
  translations: 'data/translations.json',
  settings: 'data/settings.json',
  factoryVideo: 'data/factory-video.json',
  faqs: 'data/faqs.json',
  blog: 'data/blog.json',
  blogSettings: 'data/blog-settings.json',
  quoteSection: 'data/quote-section.json',
};

const CACHE_KEY_PREFIX = '__app_ledlight_remote_cache_';
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 分钟缓存

interface RemoteDataStoreValue {
  modules: Partial<Record<RemoteDataModule, unknown>>;
  loading: boolean;
  hasRemoteData: boolean;
  refreshModule: (module: RemoteDataModule) => Promise<void>;
  refreshAll: () => Promise<void>;
  /** 直接设置某个模块的数据（绕过 fetch，用于 GitHub Pull 等已知数据来源的场景） */
  setModuleData: (module: RemoteDataModule, data: unknown) => void;
}

const RemoteDataStoreContext = createContext<RemoteDataStoreValue | null>(null);

/**
 * 从 sessionStorage 读取缓存（同步，防闪烁）
 */
function readCacheFromStorage(): Partial<Record<RemoteDataModule, unknown>> {
  const result: Partial<Record<RemoteDataModule, unknown>> = {};
  if (typeof window === 'undefined') return result;

  const now = Date.now();
  for (const [module, path] of Object.entries(MODULE_PATHS) as [RemoteDataModule, string][]) {
    try {
      const raw = sessionStorage.getItem(CACHE_KEY_PREFIX + module);
      if (!raw) continue;
      const parsed = JSON.parse(raw);
      if (!parsed?.timestamp || !parsed?.data) continue;
      if (now - parsed.timestamp > CACHE_TTL_MS) continue;
      result[module] = parsed.data;
      logger.info(`[RemoteData] cache hit: ${module} (age=${((now - parsed.timestamp) / 1000).toFixed(0)}s)`);
    } catch {
      // ignore individual cache read errors
    }
  }
  return result;
}

/**
 * 写入单个模块的缓存
 */
function writeModuleCache(module: RemoteDataModule, data: unknown) {
  try {
    sessionStorage.setItem(
      CACHE_KEY_PREFIX + module,
      JSON.stringify({ timestamp: Date.now(), data })
    );
  } catch {
    // ignore
  }
}

/**
 * 获取 GitHub 公开配置（owner/repo/branch/basePath/token）
 * 优先级：localStorage 配置 > window.__GITHUB_CONFIG__ > 空
 *
 * 注意：不使用 useGithubConfig hook 是因为 RemoteDataProvider
 * 在外层（比 GithubConfigProvider 更内），需要自己读配置。
 * 但当前嵌套是 GithubConfigProvider 在最外层，所以可以用 hook。
 */
function getGithubPublicConfig(): {
  owner: string;
  repo: string;
  branch: string;
  basePath: string;
  token: string;
  enabled: boolean;
} | null {
  if (typeof window === 'undefined') return null;

  // 尝试从 localStorage 读（scopedStorage 的 key 会加前缀，这里用原生读更安全）
  // 先尝试 scopedStorage 前缀的 key
  const tryKeys = [
    '__app_ledlight_github_config_v1',
    // scopedStorage 可能加了 appId 前缀，这里先不试，让 hook 去处理
  ];

  for (const key of tryKeys) {
    try {
      const saved = localStorage.getItem(key);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (parsed?.owner && parsed?.repo && parsed?.branch && parsed?.enabled) {
          return {
            owner: parsed.owner,
            repo: parsed.repo,
            branch: parsed.branch || 'main',
            basePath: parsed.basePath || '',
            token: parsed.token || '',
            enabled: true,
          };
        }
      }
    } catch {
      // ignore
    }
  }

  // 尝试全局注入
  const globalConfig = (window as any).__GITHUB_CONFIG__;
  if (globalConfig && globalConfig.owner && globalConfig.repo && globalConfig.enabled) {
    return {
      owner: globalConfig.owner,
      repo: globalConfig.repo,
      branch: globalConfig.branch || 'main',
      basePath: globalConfig.basePath || '',
      token: globalConfig.token || '',
      enabled: true,
    };
  }

  return null;
}

export function RemoteDataProvider({ children }: { children: ReactNode }) {
  const { config } = useGithubConfig();
  const [modules, setModules] = useState<Partial<Record<RemoteDataModule, unknown>>>(() =>
    readCacheFromStorage()
  );
  const [loading, setLoading] = useState(false);
  const failedModulesRef = useRef<Set<RemoteDataModule>>(new Set());
  const initialFetchRef = useRef(false);

  // 计算当前可用的 GitHub 配置
  const ghConfig = useMemo(() => {
    // 优先用 GithubConfigContext 的配置（已配置且启用）
    if (config.enabled && config.owner && config.repo) {
      return {
        owner: config.owner,
        repo: config.repo,
        branch: config.branch || 'main',
        basePath: config.basePath || '',
        token: config.token || '',
        enabled: true,
      };
    }
    // 否则尝试从 localStorage / 全局变量读取
    const fallback = getGithubPublicConfig();
    if (fallback) return fallback;
    return null;
  }, [config]);

  const hasRemoteData = Object.keys(modules).length > 0;

  /**
   * 拉取单个模块的远程数据
   *
   * 🔴 V121 CORS 彻底修复：
   * - 只从同源 ./data/*.json 读取（GitHub Pages 部署后 data/ 在网站根目录，无 CORS）
   * - 彻底移除 raw.githubusercontent.com 路径（有 CORS 问题）
   * - 失败直接返回 null，各 hook 自动降级到本地默认数据，绝不崩溃白屏
   *
   * 注意：GitHub 配置（token/owner/repo）不再用于前台数据读取。
   * 后台 Pull Data from GitHub 走单独的 Contents API 路径（带 Token，无 CORS）。
   */
  const fetchModule = useCallback(
    async (module: RemoteDataModule): Promise<unknown> => {
      const path = MODULE_PATHS[module];
      if (!path) {
        logger.warn(`[RemoteData] unknown module: ${module}`);
        return null;
      }

      // 唯一方式：同源 data/ 目录读取（GitHub Pages 部署场景，无 CORS，最可靠）
      try {
        const sameOriginUrl = `./${path}`;
        const sameOriginResp = await fetch(sameOriginUrl, {
          method: 'GET',
          headers: { Accept: 'application/json' },
          cache: 'no-cache',
        });

        if (sameOriginResp.ok) {
          const text = await sameOriginResp.text();
          try {
            const parsed = JSON.parse(text);
            writeModuleCache(module, parsed);
            logger.info(`[RemoteData] fetchModule success: ${module} (source=same-origin, size=${text.length})`);
            failedModulesRef.current.delete(module);
            return parsed;
          } catch (parseErr) {
            logger.error(`[RemoteData] same-origin JSON parse failed for ${module}: ${String(parseErr)}`);
            failedModulesRef.current.add(module);
            return null;
          }
        } else {
          logger.info(`[RemoteData] same-origin ${sameOriginResp.status} for ${module}, will use local defaults`);
          failedModulesRef.current.add(module);
          return null;
        }
      } catch (err) {
        logger.warn(`[RemoteData] same-origin fetch error for ${module}: ${String(err)}`);
        failedModulesRef.current.add(module);
        return null;
      }
    },
    []
  );

  /**
   * 刷新单个模块
   */
  const refreshModule = useCallback(
    async (module: RemoteDataModule) => {
      failedModulesRef.current.delete(module);
      const data = await fetchModule(module);
      if (data !== null) {
        setModules((prev) => ({ ...prev, [module]: data }));
      }
    },
    [fetchModule]
  );

  /**
   * 直接设置模块数据（用于 GitHub Pull 等已知数据来源的场景）
   * 同时写入 sessionStorage 缓存，确保后续访问也使用最新数据
   */
  const setModuleData = useCallback((module: RemoteDataModule, data: unknown) => {
    writeModuleCache(module, data);
    setModules((prev) => ({ ...prev, [module]: data }));
    logger.info(`[RemoteData] setModuleData: ${module} updated (size=${JSON.stringify(data).length})`);
  }, []);

  /**
   * 刷新所有模块
   *
   * V121 CORS 修复：仅从同源 ./data/*.json 读取，无 raw.githubusercontent.com 降级
   * 失败不崩溃，各 hook 自动降级到本地默认数据
   */
  const refreshAll = useCallback(async () => {
    setLoading(true);
    failedModulesRef.current.clear();
    logger.info('[RemoteData] refreshAll: fetching all modules...');

    const allModules = Object.keys(MODULE_PATHS) as RemoteDataModule[];
    const results: Partial<Record<RemoteDataModule, unknown>> = {};

    // 并发拉取所有模块
    const promises = allModules.map(async (module) => {
      const data = await fetchModule(module);
      if (data !== null) {
        results[module] = data;
      }
    });

    await Promise.all(promises);

    // 一次性 setState，避免多次重渲染
    setModules((prev) => ({ ...prev, ...results }));
    setLoading(false);

    const successCount = Object.keys(results).length;
    logger.info(
      `[RemoteData] refreshAll complete: ${successCount}/${allModules.length} modules loaded`
    );
  }, [fetchModule]);

  // 初始化：自动从同源 data/ 目录拉取所有模块
  // V121 CORS 修复：不再依赖 GitHub 配置，始终只从同源读取
  // 失败不崩溃，各 hook 自动降级到本地默认数据
  useEffect(() => {
    if (initialFetchRef.current) return;

    initialFetchRef.current = true;
    logger.info(
      '[RemoteData] init: starting prefetch from same-origin data/ directory (V121 CORS-free)'
    );

    // 缓存已有数据的数量
    const cachedCount = Object.keys(modules).length;
    if (cachedCount > 0) {
      logger.info(`[RemoteData] init: ${cachedCount} modules already in cache (showing immediately)`);
    }

    // 后台静默拉取最新数据
    refreshAll();
  }, [refreshAll, modules]);

  const value = useMemo<RemoteDataStoreValue>(
    () => ({
      modules,
      loading,
      hasRemoteData,
      refreshModule,
      refreshAll,
      setModuleData,
    }),
    [modules, loading, hasRemoteData, refreshModule, refreshAll, setModuleData]
  );

  return (
    <RemoteDataStoreContext.Provider value={value}>
      {children}
    </RemoteDataStoreContext.Provider>
  );
}

/**
 * 读取指定模块的远程数据
 * @param module 模块名
 * @returns 远程数据（如果加载成功且存在），否则返回 null
 *
 * 🔴 重要：此函数内部不能有任何提前 return / 条件性调用，
 * 否则会破坏 React Hook 调用顺序，导致 "Should have a queue" 错误。
 */
export function useRemoteDataStore<T = unknown>(module: RemoteDataModule): T | null {
  const ctx = useContext(RemoteDataStoreContext);
  const data = ctx?.modules[module];
  return (data as T) ?? null;
}

/**
 * 读取完整的远程数据 store（用于刷新等操作）
 */
export function useRemoteDataStoreFull(): RemoteDataStoreValue | null {
  return useContext(RemoteDataStoreContext);
}

export default RemoteDataProvider;
